class TestValidationError:
    """Test the custom ValidationError exception."""

    def test_basic_instantiation(self):
        """Test basic exception creation with just a message."""
        err = ValidationError("test error")
        assert err.message == "test error"
        assert err.errors == {}
        assert str(err) == "test error"

    def test_with_errors_dict(self):
        """Test exception with detailed error dictionary."""
        errors = {"field1": "must not be empty", "field2": "invalid type"}
        err = ValidationError("validation failed", errors=errors)
        assert err.message == "validation failed"
        assert err.errors == errors
        assert str(err) == "validation failed"

    def test_empty_errors_default(self):
        """Test that errors defaults to empty dict when not provided."""
        err = ValidationError("msg")
        assert err.errors == {}

    def test_inherits_from_exception(self):
        """Test that ValidationError is a proper Exception subclass."""
        err = ValidationError("msg")
        assert isinstance(err, Exception)
        assert isinstance(err, ValidationError)


