class TestAgentCommand:
    """Test AgentCommand schema validation."""

    # --- Valid Cases ---

    def test_valid_minimal(self):
        """Test creation with only required fields."""
        cmd = AgentCommand(action="deploy", target="node-1")
        assert cmd.action == "deploy"
        assert cmd.target == "node-1"
        assert cmd.payload is None
        assert isinstance(cmd.timestamp, datetime)
        assert cmd.priority == 0

    def test_valid_with_all_fields(self):
        """Test creation with all optional fields provided."""
        ts = datetime(2025, 1, 15, 10, 30, 0)
        cmd = AgentCommand(
            action="scale.up",
            target="cluster-alpha",
            payload={"replicas": 5},
            timestamp=ts,
            priority=50,
        )
        assert cmd.action == "scale.up"
        assert cmd.target == "cluster-alpha"
        assert cmd.payload == {"replicas": 5}
        assert cmd.timestamp == ts
        assert cmd.priority == 50

    def test_valid_action_patterns(self):
        """Test various valid action patterns."""
        valid_actions = [
            "deploy",
            "scale.up",
            "rollback_v2",
            "health-check",
            "config.set",
            "a" * 256,  # max length
        ]
        for action in valid_actions:
            cmd = AgentCommand(action=action, target="t")
            assert cmd.action == action

    def test_valid_target_lengths(self):
        """Test target field at boundary lengths."""
        cmd = AgentCommand(action="test", target="x")
        assert cmd.target == "x"

        long_target = "x" * 128
        cmd = AgentCommand(action="test", target=long_target)
        assert cmd.target == long_target

    def test_valid_priority_boundaries(self):
        """Test priority at min and max values."""
        cmd = AgentCommand(action="test", target="t", priority=0)
        assert cmd.priority == 0

        cmd = AgentCommand(action="test", target="t", priority=100)
        assert cmd.priority == 100

    def test_timestamp_defaults_to_now(self):
        """Test that timestamp defaults to current UTC time."""
        before = datetime.utcnow()
        cmd = AgentCommand(action="test", target="t")
        after = datetime.utcnow()
        assert before <= cmd.timestamp <= after

    def test_payload_none_default(self):
        """Test that payload defaults to None."""
        cmd = AgentCommand(action="test", target="t")
        assert cmd.payload is None

    def test_payload_with_dict(self):
        """Test payload accepts arbitrary dict."""
        cmd = AgentCommand(
            action="test",
            target="t",
            payload={"key": "value", "nested": {"a": 1}},
        )
        assert cmd.payload == {"key": "value", "nested": {"a": 1}}

    # --- Invalid Cases ---

    def test_invalid_action_empty(self):
        """Test that empty action raises validation error."""
        with pytest.raises(PydanticValidationError) as exc_info:
            AgentCommand(action="", target="t")
        errors = exc_info.value.errors()
        assert any(e["loc"] == ("action",) for e in errors)

    def test_invalid_action_too_long(self):
        """Test that action exceeding max length raises error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="x" * 257, target="t")

    def test_invalid_action_pattern(self):
        """Test that action with invalid characters raises error."""
        invalid_actions = [
            "deploy!",      # exclamation
            "scale up",     # space
            "cmd@host",     # @
            "test#1",       # #
            "a/b",          # slash
            "a\\b",         # backslash
        ]
        for action in invalid_actions:
            with pytest.raises(PydanticValidationError):
                AgentCommand(action=action, target="t")

    def test_invalid_target_empty(self):
        """Test that empty target raises validation error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test", target="")

    def test_invalid_target_too_long(self):
        """Test that target exceeding max length raises error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test", target="x" * 129)

    def test_invalid_priority_negative(self):
        """Test that negative priority raises error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test", target="t", priority=-1)

    def test_invalid_priority_too_high(self):
        """Test that priority > 100 raises error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test", target="t", priority=101)

    def test_invalid_priority_float(self):
        """Test that float priority is rejected (must be int)."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test", target="t", priority=50.5)

    def test_invalid_timestamp_type(self):
        """Test that non-datetime timestamp raises error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test", target="t", timestamp="2025-01-01")

    def test_invalid_payload_type(self):
        """Test that non-dict payload raises error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test", target="t", payload="not_a_dict")

    def test_missing_required_fields(self):
        """Test that missing required fields raises error."""
        with pytest.raises(PydanticValidationError):
            AgentCommand()  # missing action and target

        with pytest.raises(PydanticValidationError):
            AgentCommand(action="test")  # missing target

        with pytest.raises(PydanticValidationError):
            AgentCommand(target="test")  # missing action


