class TestSchemaIntegration:
    """Test interactions between schemas and real-world usage patterns."""

    def test_agent_command_with_data_payload(self):
        """Test AgentCommand with AgentData as payload."""
        inner_data = AgentData(content_type="text/plain", data="scan result")
        cmd = AgentCommand(
            action="process",
            target="analyzer",
            payload={"data": inner_data.dict()},
        )
        assert cmd.payload["data"]["content_type"] == "text/plain"
        assert cmd.payload["data"]["data"] == "scan result"

    def test_configuration_with_nested_validation(self):
        """Test ConfigurationSchema with complex nested features."""
        config = ConfigurationSchema(
            agent_name="coordinator",
            log_level="DEBUG",
            max_retries=5,
            timeout=120,
            features={
                "plugins": ["auth", "logging"],
                "limits": {"cpu": 0.5, "memory": 256},
                "enabled": True,
            },
        )
        assert config.features["plugins"] == ["auth", "logging"]
        assert config.features["limits"]["cpu"] == 0.5

    def test_serialization_roundtrip(self):
        """Test that schemas serialize and deserialize correctly."""
        original = AgentCommand(
            action="deploy",
            target="node-1",
            payload={"version": "2.0"},
            priority=75,
        )
        data = original.dict()
        restored = AgentCommand(**data)
        assert restored.action == original.action
        assert restored.target == original.target
        assert restored.payload == original.payload
        assert restored.priority == original.priority
        # timestamp may differ slightly due to serialization, check type
        assert isinstance(restored.timestamp, datetime)

    def test_json_serialization(self):
        """Test that schemas can be serialized to JSON."""
        cmd = AgentCommand(action="test", target="t")
        json_str = cmd.json()
        assert '"action": "test"' in json_str
        assert '"target": "t"' in json_str

        # Verify it can be parsed back
        import json as json_lib
        parsed = json_lib.loads(json_str)
        assert parsed["action"] == "test"
        assert parsed["target"] == "t"